using GK3Reborn.Formats;
using GK3Reborn.Formats.Video.H264;
using GK3Reborn.Formats.Video.Mp4;
using Xunit;

namespace GK3Reborn.Tests.Formats;

/// <summary>
/// Tests for the MP4 demuxer.
/// </summary>
/// <remarks>
/// The embedded file is the five-frame CABAC stream of <see cref="H264DecoderTests"/>
/// as FFmpeg muxes it with <c>+faststart</c>: one video track, an edit list for the
/// B-frame delay, composition offsets, and a single sync sample. Small enough to carry,
/// and it exercises every table a real clip has.
/// </remarks>
public sealed class Mp4FileTests
{
    private const string TinyMp4 =
        "";

    private static Mp4File OpenTiny() =>
        Mp4File.Open(new MemoryStream(Convert.FromHexString(TinyMp4)), "tiny.mp4", ownsStream: true);

    [Fact]
    public void The_tracks_and_sample_tables_are_read()
    {
        using Mp4File file = OpenTiny();

        Assert.Equal(1000, file.MovieTimescale);
        Assert.Equal(TimeSpan.FromMilliseconds(500), file.Duration);
        Assert.Null(file.Audio);

        Mp4Track video = Assert.IsType<Mp4Track>(file.Video);
        Assert.Equal("avc1", video.Codec);
        Assert.Equal(48, video.Width);
        Assert.Equal(32, video.Height);
        Assert.Equal(10240, video.Timescale);
        Assert.Equal(4, video.NalLengthSize);
        Assert.Single(video.SequenceParameterSets);
        Assert.Single(video.PictureParameterSets);
        Assert.Equal(5, video.Samples.Count);

        // Decode times are 1024 ticks apart; every sample is shown 2048 ticks after it is
        // decoded, and the edit list takes that delay off again.
        Assert.Equal([0, 1024, 2048, 3072, 4096], video.Samples.Select(s => s.DecodeTime));
        Assert.All(video.Samples, s => Assert.Equal(2048, s.CompositionOffset));
        Assert.Equal(2048, video.EditOffset);
        Assert.True(video.Samples[0].Sync);
        Assert.All(video.Samples.Skip(1), s => Assert.False(s.Sync));
        Assert.Equal([1217, 45, 60, 53, 53], video.Samples.Select(s => s.Size));
    }

    [Fact]
    public void Samples_read_from_the_file_decode()
    {
        using Mp4File file = OpenTiny();
        Mp4Track video = file.Video!;
        var decoder = new H264Decoder();
        decoder.Configure(video.SequenceParameterSets, video.PictureParameterSets);

        foreach (Mp4Sample sample in video.Samples)
        {
            decoder.Decode(file.Read(sample), video.NalLengthSize, sample.PresentationTime);
        }

        decoder.Flush();
        var tags = new List<long>();

        while (decoder.TryGetFrame(out DecodedFrame frame))
        {
            tags.Add(frame.Tag);
            frame.Release();
        }

        // Five frames, tagged with their presentation times, in display order.
        Assert.Equal([2048, 3072, 4096, 5120, 6144], tags);
    }

    [Fact]
    public void A_file_that_is_not_an_mp4_is_refused()
    {
        var bytes = new byte[64];
        Assert.Throws<FormatParseException>(() => Mp4File.Open(new MemoryStream(bytes), "junk"));
    }

    [Fact]
    public void A_truncated_moov_is_refused_rather_than_read_past()
    {
        byte[] whole = Convert.FromHexString(TinyMp4);
        byte[] cut = whole[..600];
        Assert.Throws<FormatParseException>(() => Mp4File.Open(new MemoryStream(cut), "cut"));
    }
}
